package com.ke.ticketsystemke.controller;import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.service.WarrantyReportService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/volt/warranty-reports")public class WarrantyReportController{private final WarrantyReportService service;public WarrantyReportController(WarrantyReportService s){service=s;}@GetMapping("/summary")WarrantyReportResponse summary(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.summary(f,a.getName());}@GetMapping("/outcomes")WarrantyReportResponse outcomes(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.outcomes(f,a.getName());}@GetMapping("/manufacturers")WarrantyReportResponse manufacturers(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.manufacturers(f,a.getName());}@GetMapping("/resolution-times")WarrantyReportResponse resolution(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.resolutionTimes(f,a.getName());}@GetMapping("/follow-up-visits")WarrantyReportResponse follow(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.followUpVisits(f,a.getName());}@GetMapping("/replacements")WarrantyReportResponse replacement(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.replacement(f,a.getName());}@GetMapping("/owners")WarrantyReportResponse owners(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.owners(f,a.getName());}@GetMapping("/documents")WarrantyReportResponse documents(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.documentReadiness(f,a.getName());}@GetMapping("/trends")WarrantyReportResponse trends(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.trends(f,a.getName());}@GetMapping("/filter-options")WarrantyReportResponse options(@ModelAttribute WarrantyReportFilter f,Authentication a){return service.options(f,a.getName());}}
